function partition(a: number[], lo: number, hi: number): number {
	const pivot = a[hi];
	let i = lo - 1;
	for (let j = lo; j < hi; j++) {
		if (a[j] <= pivot) {
			i++;
			[a[i], a[j]] = [a[j], a[i]];
		}
	}
	[a[i + 1], a[hi]] = [a[hi], a[i + 1]];
	return i + 1;
}

